CREATE TABLE t(a); CREATE INDEX ta ON t(a); INSERT INTO t(a) VALUES(1),(2); CREATE TABLE result(stage TEXT,a INTEGER); INSERT INTO result SELECT 'initial',a FROM t ORDER BY a; INSERT INTO result SELECT 'or-result',a FROM t WHERE a<2 OR a<3 ORDER BY a; CREATE TABLE change_log(a INTEGER); CREATE TRIGGER t_delete_log AFTER DELETE ON t BEGIN INSERT INTO change_log VALUES(old.a); END; PRAGMA count_changes=ON; DELETE FROM t WHERE a<2 OR a<3; PRAGMA count_changes=OFF; INSERT INTO result VALUES('deleted',(SELECT count(*) FROM change_log)); INSERT INTO result SELECT 'remaining',a FROM t ORDER BY a; DROP TRIGGER t_delete_log; DROP TABLE change_log; DROP TABLE t;